import sys
from collections import Counter

def is_prime(n):
    if n < 2:
        return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True

def can_rearrange(s):
    count = Counter(s)
    max_freq = max(count.values())
    if max_freq > (len(s) + 1) // 2:
        return False
    return True

def construct_string(s):
    count = Counter(s)
    sorted_chars = sorted(count.items(), key=lambda x: (-x[1], x[0]))
    result = [''] * len(s)
    index = 0
    for char, freq in sorted_chars:
        for _ in range(freq):
            result[index] = char
            index += 2
            if index >= len(s):
                index = 1
    return ''.join(result)

s = sys.stdin.read().strip()
if can_rearrange(s):
    result = construct_string(s)
    print("YES")
    print(result)
else:
    print("NO")
